  auto GRID_LONGITUDE_RAD__ = GRID_LONGITUDE_RAD ? _fbb.CreateVector<double>(*GRID_LONGITUDE_RAD) : 0;
  auto GRID_LATITUDE_RAD__ = GRID_LATITUDE_RAD ? _fbb.CreateVector<double>(*GRID_LATITUDE_RAD) : 0;
